use std::sync::Arc; use async_trait::async_trait; use rand::Rng; use crate::{domain::errors::DomainError,ports::{inbound::coude_steal::{CoudeStealUseCase,StealResult},outbound::coude_steal_repository::CoudeStealRepository}};
pub struct CoudeStealService{repo:Arc<dyn CoudeStealRepository>} impl CoudeStealService{pub fn new(repo:Arc<dyn CoudeStealRepository>)->Self{Self{repo}}}
#[async_trait] impl CoudeStealUseCase for CoudeStealService { async fn steal(&self,guild_id:&str,thief_id:&str,victim_id:&str,is_fourbe:bool)->Result<StealResult,DomainError>{if thief_id==victim_id{return Err(DomainError::Validation("impossible de se voler soi-meme".into()))} let(thief,victim)=self.repo.balances(guild_id,thief_id,victim_id).await?;if victim<10{return Err(DomainError::Validation("cible trop pauvre".into()))}let success=rand::thread_rng().gen_range(0..100) < if is_fourbe{50}else{30};let amount=if success{(victim/5).max(1)}else{(thief*15/100).max(1)};self.repo.transfer(guild_id,thief_id,victim_id,amount,success).await?;Ok(StealResult{success,amount})}}
